const TAX_RATE = 0.2;
var welcomeCode = "WELCOME10";

function formatPrice(amount) {
  return "$" + amount.toFixed(2);
}

const calculateTax = (subtotal) => subtotal * TAX_RATE;

function applyDiscount(total, code) {
  if (code == welcomeCode) return total * 0.9;
  return total;
}

function findItem(orders, sku) {
  for (const order of orders) {
    if (order.items) {
      for (const item of order.items) {
        if (item.sku === sku && item.inStock) {
          return item;
        }
      }
    }
  }
  return null;
}

function processOrder(order, user, coupon, region, notify) {
  let subtotal = 0;
  const unusedCount = 0;
  for (const item of order.items) {
    if (item.quantity > 0) {
      subtotal += item.price * item.quantity;
    }
  }
  if (user.isMember || user.isStaff) {
    subtotal = subtotal * 0.95;
  } else if (user.isNew) {
    subtotal = applyDiscount(subtotal, coupon);
  }
  let shipping = 5;
  switch (region) {
    case "local":
      shipping = 0;
      break;
    case "abroad":
      shipping = 20;
      break;
    default:
      shipping = 5;
  }
  const tax = region === "abroad" ? 0 : calculateTax(subtotal);
  const total = subtotal + shipping + tax;
  if (notify && user.email) {
    console.log("Sending receipt to " + user.email);
  }
  return { total, label: formatPrice(total) };
}

function OrderSummary({ order }) {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <section>
      <button onClick={() => setIsOpen(!isOpen)}>Details</button>
      {isOpen && <p>Total: {formatPrice(order.total)}</p>}
    </section>
  );
}

export default OrderSummary;
